include/glhist.h has a couple of enumerated typedefs in which the
enum name and typename are the same.  This patch changes them to
match the other declarations in the file, which use a leading underscore
for the enum name.

--- glhist.h-orig       Fri Oct 30 14:14:25 1998
+++ glhist.h    Fri Oct 30 14:17:59 1998
@@ -21,7 +21,7 @@

 #include "ntypes.h"

-typedef enum gh_SortColumn
+typedef enum _gh_SortColumn
 {
    eGH_NoSort = -1,
    eGH_NameSort,
@@ -50,7 +50,7 @@
     char *  pszName;
 }gh_HistEntryData;

-typedef enum gh_FilterOp
+typedef enum _gh_FilterOp
 {
    eGH_FOEquals,
    eGH_FOEqualsNot,
@@ -64,7 +64,7 @@
    eGH_FOHasNot
 }gh_FilterOp;

-typedef enum gh_FilterLogOp
+typedef enum _gh_FilterLogOp
 {
    eGH_FLOAnd,
    eGH_FLOOr
@@ -72,8 +72,8 @@

 typedef struct _gh_FilterCondition
 {
-   enum gh_SortColumn enCol;
-   enum gh_FilterOp   enOp;
+   gh_SortColumn enCol;
+   gh_FilterOp   enOp;

    union
    {
@@ -157,7 +157,7 @@
 // Context/Handle based functions to retrieve a pseudo cursor on the
 // Global History list (using a specified sort/index).
 */
-extern GHHANDLE        GH_GetContext( enum gh_SortColumn   enGHSort,
+extern GHHANDLE        GH_GetContext( gh_SortColumn        enGHSort,
                                       gh_Filter *          pFilter,
                                       GHISTORY_NOTIFYPROC  pfNotifyProc,
                                       GHURHANDLE
hUR,

GetFont() was declared as taking a const argument, which the motif
version then attempted to modify.  These patches remove the "const":

--- nsIFontMetrics.h-orig       Fri Oct 30 15:03:18 1998
+++ nsIFontMetrics.h    Fri Oct 30 15:03:34 1998
@@ -125,7 +125,7 @@
   /**
    * Returns the font associated with these metrics
    */
-  NS_IMETHOD  GetFont(const nsFont *&aFont) = 0;
+  NS_IMETHOD  GetFont(nsFont *&aFont) = 0;

   /**
    * Returns the font handle associated with these metrics

--- motif/nsFontMetricsUnix.h-orig      Fri Oct 30 15:00:46 1998
+++ motif/nsFontMetricsUnix.h   Fri Oct 30 15:01:03 1998
@@ -57,7 +57,7 @@
   NS_IMETHOD  GetMaxDescent(nscoord &aDescent);
   NS_IMETHOD  GetMaxAdvance(nscoord &aAdvance);

-  NS_IMETHOD  GetFont(const nsFont*& aFont);
+  NS_IMETHOD  GetFont(nsFont*& aFont);
   NS_IMETHOD  GetFontHandle(nsFontHandle &aHandle);

 protected:

--- motif/nsFontMetricsUnix.cpp-orig    Fri Oct 30 15:00:37 1998
+++ motif/nsFontMetricsUnix.cpp Fri Oct 30 15:01:14 1998
@@ -334,7 +334,7 @@
   return NS_OK;
 }

-NS_IMETHODIMP nsFontMetricsUnix :: GetFont(const nsFont*& aFont)
+NS_IMETHODIMP nsFontMetricsUnix :: GetFont(nsFont*& aFont)
 {
   aFont = mFont;
   return NS_OK;

