<SCRIPT>
var os1 = "'kibo.constructor: ' + kibo.constructor + '\\n' + 'instanceOf (kibo,
NetGod): ' + instanceOf (kibo, NetGod) + '\\n' + 'instanceOf (kibo, God): ' +
instanceOf (kibo, God) + '\\n'";
